    z_t62_t* boxed = (z_t62_t*)z_xmalloc(sizeof(z_t62_t));
    *boxed = z_t62_new(v);
    out.tag = Z_OPTION_STRING_TAG_SOME;
    out.data = boxed;
    return out;
